// @ts-expect-error `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

export { PresenceRoom } from "./worker/presence-room";
export { WorldRoom } from "./worker/world-room";
export { PushbulletBridge } from "./worker/pushbullet-bridge";
export { GiveawayHub } from "./worker/giveaway-hub";
export { TicketGateway } from "./worker/ticket-gateway";

type Env = {
  PRESENCE: DurableObjectNamespace;
  WORLD: DurableObjectNamespace;
  PB_BRIDGE: DurableObjectNamespace;
  TICKET_GW: DurableObjectNamespace;
  AUTH_SECRET?: string;
  AOS_BRIDGE_SECRET?: string;
  [key: string]: unknown;
};

const PRESENCE_PATH = "/api/presence/ws";
const WORLD_PATH = "/api/world/ws";
const WILD_PATH = "/api/wild/ws";

function roomName(url: URL) {
  const room = (url.searchParams.get("room") || "").toLowerCase().replace(/[^a-z0-9_-]/g, "");
  return room.slice(0, 40) || url.hostname.toLowerCase();
}

/** Pushbullet 토큰을 저장한 상점마다 PushbulletBridge 를 깨워 알림 스트림을 유지한다 */
async function syncPushbulletBridges(env: Env, ctx: ExecutionContext) {
  const secret = (env.AOS_BRIDGE_SECRET || env.AUTH_SECRET || "").trim();
  if (secret.length < 8) return;
  const res: Response = await handler.fetch(
    new Request("https://vendix.team/api/charges/auto/bridges", {
      headers: { "x-vendix-bridge-secret": secret },
    }),
    env,
    ctx,
  );
  if (!res.ok) {
    console.log("bridge list failed", res.status);
    return;
  }
  const data = (await res.json()) as { shops?: { slug: string; pushbulletToken: string; origin: string }[] };
  await Promise.all(
    (data.shops ?? []).map(async (s) => {
      const stub = env.PB_BRIDGE.get(env.PB_BRIDGE.idFromName(`pb:${s.slug}`));
      const r = await stub.fetch("https://pushbullet-bridge/sync", {
        method: "POST",
        body: JSON.stringify({ slug: s.slug, token: s.pushbulletToken, origin: s.origin }),
      });
      console.log("bridge sync", s.slug, r.status, await r.text());
    }),
  );
}

/** 슬래시 명령 정의가 바뀌었으면(해시 비교) Discord 에 다시 등록한다 */
async function syncDiscordCommands(env: Env, ctx: ExecutionContext) {
  const secret = (env.AOS_BRIDGE_SECRET || env.AUTH_SECRET || "").trim();
  if (secret.length < 8) return;
  const res: Response = await handler.fetch(
    new Request("https://vendix.team/api/discord/sync-commands", {
      method: "POST",
      headers: { "x-vendix-bridge-secret": secret },
    }),
    env,
    ctx,
  );
  console.log("discord command sync", res.status, (await res.text()).slice(0, 200));
}

/** AI 가 켜진 열린 티켓이 있으면 TicketGateway 를 붙여 두고, 없으면 닫는다 */
async function syncTicketGateway(env: Env, ctx: ExecutionContext) {
  const secret = (env.AOS_BRIDGE_SECRET || env.AUTH_SECRET || "").trim();
  if (secret.length < 8) return;
  const res: Response = await handler.fetch(
    new Request("https://vendix.team/api/discord/ticket-ai", {
      method: "POST",
      headers: { "content-type": "application/json", "x-vendix-bridge-secret": secret },
      body: JSON.stringify({ op: "config" }),
    }),
    env,
    ctx,
  );
  if (!res.ok) {
    console.log("ticket gateway config failed", res.status);
    return;
  }
  const config = (await res.json()) as { token?: string; channels?: string[] };
  const stub = env.TICKET_GW.get(env.TICKET_GW.idFromName("does"));
  const r = await stub.fetch("https://ticket-gateway/", {
    method: "POST",
    body: JSON.stringify(config.channels?.length ? config : { stop: true }),
  });
  console.log("ticket gateway sync", config.channels?.length ?? 0, r.status);
}

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext) {
    const url = new URL(request.url);
    if (url.pathname === PRESENCE_PATH || url.pathname === WORLD_PATH || url.pathname === WILD_PATH) {
      if (request.headers.get("upgrade")?.toLowerCase() !== "websocket") {
        return new Response("Expected WebSocket", { status: 426 });
      }
      if (url.pathname === WORLD_PATH) {
        const id = env.WORLD.idFromName(`world:${roomName(url)}`);
        return env.WORLD.get(id).fetch(request);
      }
      if (url.pathname === WILD_PATH) {
        const id = env.WORLD.idFromName(`wild:${roomName(url)}`);
        return env.WORLD.get(id).fetch(request);
      }
      const id = env.PRESENCE.idFromName(roomName(url));
      return env.PRESENCE.get(id).fetch(request);
    }
    return handler.fetch(request, env, ctx);
  },
  async scheduled(_controller: ScheduledController, env: Env, ctx: ExecutionContext) {
    ctx.waitUntil(syncPushbulletBridges(env, ctx));
    ctx.waitUntil(syncDiscordCommands(env, ctx));
    ctx.waitUntil(syncTicketGateway(env, ctx));
  },
} satisfies ExportedHandler<Env>;
